'use strict';
window.BookNotes=(()=>{
 let data={lessons:[]},selectedChapter=1,selectedDate='all';
 const chapterLabel=n=>`Chapter ${n}`,partLabel=id=>window.StudyEngine.courseParts.find(p=>p.id===id)?.label||id;
 function cards(source=data){return source.lessons.flatMap(l=>l.entries.filter(v=>!(l.importVocabularyAsCustom&&v.kind==='vocabulary')).map(v=>({id:'bn:'+l.id+':'+v.key,korean:v.korean,topicId:v.topic||'',forms:[v.korean],answer:v.meaning,quizAnswer:v.meaning,note:v.note||'',categories:['Book notes',v.kind==='grammar'?'Book grammar':'Book vocabulary','Book chapter '+l.chapter,'Book day '+l.date],sourcePages:[],occurrences:[],count:1,important:false,learned:false,studyRef:{chapter:l.chapter,part:l.part,date:l.date,lesson:l.id,kind:v.kind},pronunciation:v.pronunciation||v.korean,dictionaryUrl:'https://krdict.korean.go.kr/eng/mainAction',memoryHint:v.kind==='grammar'?{type:'Grammar pattern',text:v.note||v.meaning}:null})));}
 function init(source){data=source;return cards(source)}
 function seed(c){let changed=false;for(const l of data.lessons){const key='lesson-seed:'+l.id;if(!l.reportedCompletion||c.books[key])continue;c.books['course-'+l.chapter]=false;c.books.course=false;window.StudyEngine.recordCoursePart(c,l.date,l.chapter,l.part,true);c.books[key]=true;const session=c.sessions[l.date];session.coveredCourse=(session.coveredCourse||[]).filter(n=>n!==l.chapter);session.tasks=[...new Set([...session.tasks.filter(id=>id!=='exercises'),'course'])];const plan=c.dayPlans[l.date]||window.StudyEngine.makePlan(c,l.date,window.StudyHub.getChapters());plan.course={chapter:l.chapter,part:l.part,block:window.StudyEngine.partBlock(l.part)};plan.exercise=window.StudyEngine.nextExercise(c,l.chapter);c.dayPlans[l.date]=plan;changed=true}return changed}
 function pronounce(text){if(!('speechSynthesis'in window)||!window.SpeechSynthesisUtterance){toast('Korean pronunciation needs a Korean text-to-speech voice in this browser.');return}const voices=window.speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.toLowerCase().startsWith('ko'));if(!voice){toast('No Korean voice is available yet. Enable a Korean voice on your computer, then try again.');return}window.speechSynthesis.cancel();const line=new SpeechSynthesisUtterance(text);line.lang='ko-KR';line.voice=voice;line.rate=.8;window.speechSynthesis.speak(line)}
 function render(){const all=words.filter(w=>w.studyRef),chapterCards=all.filter(w=>w.studyRef.chapter===selectedChapter),dates=[...new Set(chapterCards.map(w=>w.studyRef.date))].sort(),current=chapterCards.filter(w=>selectedDate==='all'||w.studyRef.date===selectedDate),shownDates=[...new Set(current.map(w=>w.studyRef.date))].sort().reverse();$('#hubBody').innerHTML=`<article class="hub-card"><h3>Book notes</h3><div class="planner-options"><label for="notesChapter">Chapter<select id="notesChapter">${Array.from({length:15},(_,i)=>`<option value="${i+1}" ${selectedChapter===i+1?'selected':''}>Chapter ${i+1}</option>`).join('')}</select></label><label for="notesDate">Study day<select id="notesDate"><option value="all">All study days</option>${dates.map(d=>`<option value="${d}" ${selectedDate===d?'selected':''}>${d}</option>`).join('')}</select></label></div><button class="btn" id="notesVocab">Study vocabulary (${current.filter(w=>w.studyRef.kind==='vocabulary').length})</button> <button class="small-btn" id="notesGrammar">Study grammar (${current.filter(w=>w.studyRef.kind==='grammar').length})</button> <button class="small-btn" id="notesQuiz">Test vocabulary</button> <button class="small-btn" id="notesType">Type Korean</button></article>${shownDates.map(date=>`<details class="hub-card note-day"><summary>${date}<span>${current.filter(w=>w.studyRef.date===date).length} cards · Chapter ${selectedChapter}</span></summary><div class="note-day-body">${[['grammar','Grammar structures'],['vocabulary','Vocabulary']].map(([kind,label])=>`<h4>${label}</h4>${current.filter(w=>w.studyRef.date===date&&w.studyRef.kind===kind).map(w=>`<div class="book-note-row"><strong lang="ko">${e(w.korean)}</strong><span>${e(w.answer)}</span><button class="small-btn" data-speak="${e(w.id)}" aria-label="Listen to ${e(w.korean)}">🔊</button>${w.custom?`<button class="text-link" data-edit-word="${e(w.id)}">Edit / delete</button>`:''}${w.note?`<small>${e(w.note)}</small>`:''}</div>`).join('')||'<p class="quiet">No cards of this kind on this day.</p>'}`).join('')}</div></details>`).join('')||'<article class="hub-card"><p>No chapter notes yet. Add your words below.</p></article>'}<details class="hub-card add-notes"><summary>Add chapter vocabulary</summary>${window.Vocabulary.form(selectedChapter)}</details>`;$('#notesChapter').onchange=()=>{selectedChapter=+$('#notesChapter').value;selectedDate='all';render()};$('#notesDate').onchange=()=>{selectedDate=$('#notesDate').value;render()};$('#notesVocab').onclick=()=>window.StudyHub.openStack(`Book vocabulary:${selectedChapter}:${selectedDate}`);$('#notesGrammar').onclick=()=>window.StudyHub.openStack(`Book grammar:${selectedChapter}:${selectedDate}`);document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>{const w=all.find(w=>w.id===b.dataset.speak);pronounce(w.pronunciation||w.korean)});document.querySelectorAll('[data-edit-word]').forEach(b=>b.onclick=()=>window.Vocabulary.edit(b.dataset.editWord));const deleted=(state.customWords||[]).filter(w=>w.deleted);if(deleted.length){const trash=document.createElement('details');trash.className='hub-card';trash.innerHTML='<summary>Deleted words ('+deleted.length+')</summary>'+deleted.map(w=>`<p>${e(w.korean)} · ${e(w.answer)} <button class="small-btn" data-restore-word="${e(w.id)}">Restore</button></p>`).join('');$('#hubBody').appendChild(trash);document.querySelectorAll('[data-restore-word]').forEach(b=>b.onclick=()=>{window.Vocabulary.remove(b.dataset.restoreWord,false);render()})}$('#notesQuiz').onclick=()=>window.StudyHub.startPractice(`Book vocabulary:${selectedChapter}:${selectedDate}`,'quiz');$('#notesType').onclick=()=>window.StudyHub.startPractice(`Book vocabulary:${selectedChapter}:${selectedDate}`,'typing');window.Vocabulary.bind()}

 function importVocabulary(){if(!window.Vocabulary)return false;let changed=false;state.customWords=state.customWords||[];for(const lesson of data.lessons.filter(l=>l.importVocabularyAsCustom))for(const v of lesson.entries.filter(v=>v.kind==='vocabulary')){const id='custom:'+lesson.id.replace(/[^a-zA-Z0-9-]/g,'-')+'-'+v.key;const existing=state.customWords.find(w=>w.id===id);if(existing){if(existing.korean===v.korean){const forms=[...new Set([...(existing.forms||[existing.korean]),...v.forms||[]])];if(JSON.stringify(forms)!==JSON.stringify(existing.forms)){existing.forms=forms;changed=true}}continue;}const importKey='vocabulary-import:'+lesson.id+':'+v.key;if(lesson.deduplicateSameDay){if(state.curriculum.books[importKey])continue;state.curriculum.books[importKey]=true;changed=true;const same=state.customWords.find(w=>w.studyRef?.date===lesson.date&&w.studyRef.chapter===lesson.chapter&&w.korean.normalize('NFKC').replace(/\s+/g,'')===v.korean.normalize('NFKC').replace(/\s+/g,''));if(same)continue;}const card=window.Vocabulary.make(id,v.korean,v.meaning,lesson.chapter,lesson.part,lesson.date,'Dictated chapter vocabulary');card.forms=[...new Set([v.korean,...v.forms||[]])];card.note=v.note||'';card.pronunciation=v.pronunciation||v.korean;state.customWords.push(card);const namedTopic=v.topicName&&window.VocabularyHub?.config().topics.find(t=>t.name.trim().toLowerCase()===v.topicName.toLowerCase());window.VocabularyHub?.assign(id,namedTopic?.id||v.topic||'general');changed=true}if(changed)window.Vocabulary.sync();return changed}
 return{init,cards,seed,render,pronounce,importVocabulary,selectChapter:n=>{selectedChapter=n;selectedDate='all'}};
})();
